//! 🧪️ Native child payloads preserve the actual cold converter's exact ordered parameter strings.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
fn clock()->Option<u64>{Some(1000)}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768)}
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn close(mut work:WidgetNodeWork,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant){
 work.begin_close();for turn in 0..10000{if work.terminal_is_empty(){break}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|work.close_step(grant))?;Ok(())}));assert!(turn+1<10000)}assert!(work.terminal_is_empty());drop(work);
 while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}
}
fn input_node(case:&serde_json::Value)->FlowNode{FlowNode{id:case["id"].as_str().unwrap().into(),kind:case["kind"].as_str().unwrap().into(),label:case["label"].as_str().unwrap().into(),params:case["params"].as_array().unwrap().iter().map(|p|FlowParam{key:p["key"].as_str().unwrap().into(),value:p["value"].as_str().unwrap().into()}).collect(),position:Default::default()}}
fn receive(node:&FlowNode,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant)->Widget{
 use crate::editor::flow::host::composed_source::{FlowNodeReceiveWork,FlowNodeReceiveOutput};
 let mut work=FlowNodeReceiveWork::new();let mut output=None;
 for turn in 0..10000{output=native(caller,decoder,g,|cx|{for _ in 0..512{let before=(cx.retained_progress(),cx.fuel_remaining());if let Some(output)=work.step(node,cx)?{return Ok(Some(output))}if cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.fuel_remaining()){break}}Ok(None)});if output.is_some(){break}assert!(turn+1<10000)}
 work.begin_close();for turn in 0..10000{if work.terminal_is_empty(){break}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(g.maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|work.close_step(grant))?;Ok(())}));assert!(turn+1<10000)}assert!(work.terminal_is_empty());drop(work);
 let FlowNodeReceiveOutput{widget,layout_id}=output.unwrap();let mut original=Some(layout_id);let mut retirement=RetainedCloneClose::default();
 for turn in 0..10000{if original.is_none()&&retirement.is_empty(){break}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=if retirement.is_empty(){retirement.next_owner_demands::<String>(original.is_some(),&None,g.maximum_copy_bytes)?}else{retirement.demands(g.maximum_copy_bytes)?};close_original_retained_step(cx,d,|grant|if retirement.is_empty(){let turn=retirement.begin_granted(&mut original,grant);RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}else{retirement.step_granted(grant)})?;Ok(())}));assert!(turn+1<10000)}assert!(original.is_none()&&retirement.is_empty());widget
}

#[test]
fn original_owned_widget_node_matches_exact_cold_parameters_and_200_call_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🪆️composed-source/🧩️node/🧪️laws/📁️cases.json")).unwrap();
 for(items,copy,calls)in[(1,4096,10000),(512,32768,200)]{for case in fixture["cases"].as_array().unwrap(){
  let source=input_node(case);let cold=crate::schema::widget_from_node(&source);let position=WidgetLayout{x:17.5,y:-9.0};let expected=crate::schema::flow_content_node_from_working(&cold,Some(&position));cold.retire_cold();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let original=receive(&source,&mut caller,&mut decoder,g);let id=semio_framework_artifact_flow_flow::widget_id_for(&original).as_ptr();let mut work=WidgetNodeWork::new(original,position);let mut output=None;
  for turn in 0..calls{let before=(work.phase,work.index);assert!(native(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..g},|cx|work.step(cx)).is_none());assert_eq!((work.phase,work.index),before);assert_eq!(caller.receipt(),Default::default());output=native(&mut caller,&mut decoder,g,|cx|work.step(cx));if output.is_some(){break}assert!(turn+1<calls,"widget exhausted original opportunity")}
  let output=output.unwrap();assert_eq!(output,expected);assert_eq!(output.id.as_ptr(),id);for p in &output.params{if matches!(p.key.as_str(),"inputPorts"|"outputPorts"){let library:Vec<String>=serde_json::from_str(&p.value).unwrap();assert_eq!(serde_json::to_string(&library).unwrap(),p.value)}}work.restore_output(output);expected.retire_cold();close(work,&mut caller,&mut decoder,g);caller.retire(g);
 }}
 for stop in [0,1,7,17,50]{let source=input_node(&fixture["cases"][0]);let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let original=receive(&source,&mut caller,&mut decoder,g);let mut work=WidgetNodeWork::new(original,WidgetLayout{x:0.0,y:0.0});for _ in 0..stop{if let Some(output)=native(&mut caller,&mut decoder,g,|cx|work.step(cx)){work.restore_output(output);break}}caller.cancel().cancel_now();let before=(work.phase,work.index);assert!(native(&mut caller,&mut decoder,g,|cx|work.step(cx)).is_none());assert_eq!((work.phase,work.index),before);close(work,&mut caller,&mut decoder,g);caller.retire(g);}
}
